"""Select the fixed v2 specialist only after its complete preservation gate."""
import json,sys,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];sys.path.insert(0,str(ROOT/'src'))
from gameboy_agent.dataset import sha256
READ=lambda p:json.loads(Path(p).read_text())
OUT=ROOT/'runs/navigation-cliff-specialists-v2'

def main():
 report=READ(OUT/'result.json');plan=READ(OUT/'plan.json');assert report['eligible'] and all(report['gates'].values());assert not report['reserved_evaluation_used']
 assert len(report['routes'])==9 and all(r['status']=='success' and r['waypoints']==4 and not r['damage'] for r in report['routes'])
 assert [report['local_panels'][n]['successes'] for n in ['original','additional','fresh']]==[46,43,46]
 assert all(not p['lost'] and not p['damage'] and not p['deaths'] for p in report['local_panels'].values())
 assert len(report['resumes'])==3 and all(r['verified'] for r in report['resumes']) and any(r['kind']=='route_cliff' for r in report['resumes'])
 assert len(report['replays'])==12 and all(r['replay_verified'] for r in report['replays'])
 assert sha256(ROOT/report['candidate_path'])==report['candidate_sha256'] and sha256(OUT/'plan.json')==report['training_plan_sha256'] and sha256(OUT/'evaluation-plan.json')==report['evaluation_plan_sha256']
 for p,h in plan['baseline_hashes'].items():assert sha256(ROOT/p)==h
 config=ROOT/'configs/navigation_experiment.json';old=READ(config)
 with (OUT/'selection-before.json').open('x') as f:json.dump(old,f,indent=2)
 new={**old,'policy_path':report['candidate_path'],'policy_sha256':report['candidate_sha256'],'architecture':'frozen_v7_with_two_final_goal_feedforward_specialists','goal_specialists':plan['goals'],'supervision':'verified_live_continuous_successes_and_teacher_corrected_paths_with_original_final_goals','live_development_result':'runs/navigation-cliff-specialists-v2/result.json','selection_reason':'9/9 known development routes and 36/36 waypoints, preserving all 135 safe local successes, all seven specialist-v1 routes, original chains, zero damage/deaths, and exact replay plus three resume checks. Known-goal specialists; general detour planning remains unevaluated.','previous_policy_path':old['policy_path'],'previous_policy_sha256':old['policy_sha256'],'route_successes':9,'route_waypoints_reached':36,'route_result':'reports/navigation-cliff-specialists-v2.json'}
 config.write_text(json.dumps(new,indent=2)+'\n')
 focus=ROOT/'configs/research_focus.json';d=READ(focus);d.update(status='navigation_reliability_milestone_complete',selected_policy=new['policy_path'],selected_policy_sha256=new['policy_sha256'],latest_result=new['route_result'],latest_audit='reports/cliff-live-corrections-v1.json',candidate='configs/navigation_cliff_specialists_v2_candidate.json',next_step='All nine known routes now pass. Before broader claims, freeze a separate development stress protocol for the two known-goal specialists; do not consume reserved evaluation or restart sword reduction without a new instruction.',note='Research priorities, not runtime toggles. Selected navigation advanced after complete preservation checks; fixed sword controller and paused sword-reduction priority are unchanged.');focus.write_text(json.dumps(d,indent=2)+'\n')
 candidate=dict(status='selected_experimental',plan='runs/navigation-cliff-specialists-v2/plan.json',plan_sha256=sha256(OUT/'plan.json'),candidate_path=new['policy_path'],candidate_sha256=new['policy_sha256'],result=new['route_result'],training_performed=True,evaluation_completed=True,selection_changed=True,previous_policy=old['policy_path'],sword_reduction='paused',scope='Two exact final-goal specialists. Runtime uses original goals and learned physical actions; no intermediate teacher waypoints.')
 (ROOT/'configs/navigation_cliff_specialists_v2_candidate.json').write_text(json.dumps(candidate,indent=2)+'\n')
 p=ROOT/'configs/navigation_cliff_specialists_candidate.json';d=READ(p);d.update(status='eligible_superseded_by_v2',selection_changed=False,superseded_by='configs/navigation_cliff_specialists_v2_candidate.json');p.write_text(json.dumps(d,indent=2)+'\n')
 (OUT/'selection.json').write_text(json.dumps(dict(previous_config_sha256=sha256(OUT/'selection-before.json'),selected_config_sha256=sha256(config),result_sha256=sha256(OUT/'result.json'),candidate_sha256=new['policy_sha256'],all_gates_passed=True),indent=2))
 p=ROOT/'docs/NAVIGATION_CLIFF_SPECIALISTS.md';s=p.read_text().replace('Its final local and replay/resume evaluation is in progress; selection awaits those checks.', 'All local preservation, exact replay and three pause/resume checks pass. It is now the selected experimental navigator, replacing v7.');s+='''\n## Final v2 acceptance\n\nSelected after **9/9 routes and 36/36 waypoints**, all 135 safe local successes preserved (46/48, 43/48, 46/48), and 3/3 original continuous chains. Zero local/route damage or deaths. All 192 local rollouts and 12 route/chain runs replay exactly; original v7 reruns match historical fingerprints. Paired starts match. All three pause/resume checks match uninterrupted outputs, including a pause inside the cliff goal. All frozen gates pass; 66 tests pass.\n\nResult: `reports/navigation-cliff-specialists-v2.json`. Selection: `configs/navigation_experiment.json` and `configs/navigation_cliff_specialists_v2_candidate.json`. V7 and eligible specialist v1 remain available. The selected checkpoint SHA-256 is `9d2b24b28be5289fc3d32d85d46faa1835ca2068d73a1e8790630d77dbaf85ec`.\n\nA 64-second silent MP4 of the learned house loop is at `runs/videos/learned-cliff-loop-v2/cliff-loop.mp4`. It renders actual emulator frames at native speed, verifies the exact completed-run fingerprint, and adds a two-second final presentation hold. It is a learned policy replay, not a teacher demonstration. Representative frames were visually inspected.\n''';p.write_text(s)
 p=ROOT/'README.md';s=p.read_text();a=s.index('The selected experimental navigator');b=s.index('Repository source lives here;',a);s=s[:a]+'''The selected experimental navigator completes **9/9 four-goal routes** and
preserves **46/48, 43/48, and 46/48** successes across the three local panels,
with zero damage or deaths. All three cliff loops and all three original
sword-to-destination chains succeed, with exact replay and pause/resume checks.
It uses two learned final-goal specialists over a frozen v7 fallback. See the
[learned cliff specialist experiment](docs/NAVIGATION_CLIFF_SPECIALISTS.md) and
[versioned results](reports/navigation-cliff-specialists-v2.json). These are known
development/training cases, not general detour-planning evidence; reserved
evaluation remains untouched.

'''+s[b:];p.write_text(s)
 p=ROOT/'docs/CLIFF_SUPERVISION_REPAIR.md';s=p.read_text();s+='\nThe subsequent specialist investigation completes all nine known routes while preserving every safe local success. See `docs/NAVIGATION_CLIFF_SPECIALISTS.md`; the v9 rejection above remains unchanged.\n';p.write_text(s)
 p=ROOT/'RICE_SESSION_HANDOFF.md'
 with p.open('a') as f:f.write('''\n\n## Current selection — cliff specialists v2, all nine routes pass\n\nUser asked to resolve the cliff stalls. Completed diagnosis, two fixed learned specialist candidates, bounded teacher probes, fresh live corrections, full preservation evaluation and a learned replay video. This update supersedes the previous selected-v7/unsolved-cliff status. Read `docs/NAVIGATION_CLIFF_SPECIALISTS.md`.\n\nSelected checkpoint: `runs/navigation-cliff-specialists-v2/model/epoch-256.pt`, SHA-256 `9d2b24b28be5289fc3d32d85d46faa1835ca2068d73a1e8790630d77dbaf85ec`. Configuration: `configs/navigation_experiment.json`; status remains experimental_not_default. It contains the frozen v7 fallback and two same-architecture feed-forward experts keyed by the exact original final goals E2 (64,64) and E2 (36,121). Existing 250-feature contract, normalization and previous-movement mask are unchanged. No runtime teacher waypoints, route index, demonstration cursor, search or scripted action sequence. Known-goal specialization is not general navigation or game completion.\n\nDiagnosis physically verified v9's goal-aligned upward stall under the cliff and all three v7 failures from safe teacher cliff endpoints. A first specialist candidate trained on existing data reached 7/9 routes, 32/36 waypoints, preserving all six v7 routes and 135 safe local successes. Beach cliff loop passed; house oscillated in upper E2 and approach oscillated in E1. That intermediate checkpoint remains eligible and preserved.\n\nA separate clean-teacher lane probe produced nine safe 99–103-action approaches, but only one safe continuous return. A second return probe produced one safe success out of nine. These diagnostic paths are excluded from v2 training: faster safe arrival alone did not establish continuous safety.\n\nCollected corrections on actual v1 trajectories at predetermined failure regions. Canonical house/approach/beach cliff paths have 196/92/159 actions; their unchanged learned-v1 returns complete safely in 73/81/83 actions. All fresh features and final fingerprints independently replay; prefixes connect exactly. Alternate house phase caused three return damage and was excluded. Three canonical cliff paths total 447 rows, plus 14 local-anchor rows; shortest-suffix curation yields 418 states with zero conflicting action labels.\n\nV2 updates only the cliff-goal expert from v1, for 256 fixed epochs with correction-entry weighting. V7 fallback, v1 return expert, normalization and mask are independently verified unchanged. Only final checkpoint evaluated. Training fit 99.5% movement / 100% buttons is supplementary, not the success claim.\n\nFINAL: **9/9 routes, 36/36 waypoints**, local panels **46/48, 43/48, 46/48**, all **135 safe local successes preserved**, **3/3 original chains**, zero local/route damage and deaths. Learned cliff/return actions: house 194/73, beach 157/81, approach 92/81. All 192 local and 12 route/chain runs replay exactly; original v7 historical fingerprints and paired starts match. Three exact pause/resume checks pass, including inside the cliff goal. All 66 tests pass. Results: `reports/navigation-cliff-specialists-v2.json`. Selection updates recorded in `runs/navigation-cliff-specialists-v2/selection.json`; previous config snapshot preserved there.\n\nVerified learned house-loop recording: `runs/videos/learned-cliff-loop-v2/cliff-loop.mp4`, 64 seconds, silent, native emulator speed plus two-second end hold. Actual final fingerprint matches the successful learned run; representative frames visually checked. This is not a teacher recording.\n\nSword reduction remains paused and the fixed sword controller is unchanged. All cases are known development; 96 reserved evaluation specifications remain untouched. V7, rejected candidates, teacher artifacts and all pre-existing uncommitted work are preserved. No commits or uploads. Next work, if requested, should freeze a separate development stress protocol for these exact-goal specialists before broader claims. Do not resume sword reduction automatically.\n''')
 for source,name in [('/tmp/cliff-specialists-tests.log','tests.log'),('/tmp/cliff-specialists-v2-training.log','training.log')]:shutil.copy2(source,OUT/name)
 print('SELECTED',new['policy_path'],new['policy_sha256'])
if __name__=='__main__':main()
